                    raise UsageError("filter: no column name before the operator in %r" % text)
                return text[:at], op, text[at + len(op):]
    raise UsageError("filter: no operator (one of %s) in %r" % (" ".join(FILTER_OPERATORS), text))


def _holds(cell, op, value, number):
    """Whether one cell satisfies one condition; `number` is the Decimal of VALUE or None."""
    if op == "~":
        return _icontains(cell, value)
    left = to_decimal(cell) if number is not None else None
    a, b = (left, number) if left is not None else (cell, value)
    return {"==": a == b, "!=": a != b, ">=": a >= b, "<=": a <= b, ">": a > b, "<": a < b}[op]


def cmd_filter(args, opts):
    _need_args(args, 2, "filter FILE CONDITION...", at_least=True)
    conditions = [_parse_condition(c) for c in args[1:]]
    table = load(args[0])
    tests = [(table.index(column), op, value, to_decimal(value)) for column, op, value in conditions]
    return table.with_rows([r for r in table.rows if all(_holds(r[at], op, value, num) for at, op, value, num in tests)])


COMMANDS = {
    "show": (cmd_show, "show FILE", "print a table"),
    "head": (cmd_head, "head FILE N", "the first N rows"),
    "cols": (cmd_cols, "cols FILE", "the column names, numbered"),
    "apply": (cmd_apply, "apply FILE COLUMN TRANSFORM...", "run transforms over one column"),
    "sort": (cmd_sort, "sort FILE KEY...", "sort rows by one or more keys"),
    "filter": (cmd_filter, "filter FILE CONDITION...", "keep the rows where every condition holds"),
}


# --- the command line ----------------------------------------------------------------------------------------

def usage_text():
    lines = ["usage: %s [--format text|csv|json] [--kind inner|left] [--keep first|last] COMMAND ARGS..." % PROG, "", "commands:"]
    width = max(len(u) for _, u, _ in COMMANDS.values())
    for _, use, what in COMMANDS.values():
        lines.append("  %s  %s" % (use.ljust(width), what))
    return "\n".join(lines) + "\n"


def parse_args(argv):
    """(command, positional arguments, options) from the command line."""
    opts, rest, i = {name: values[0] for name, values in OPTIONS.items()}, [], 0
    while i < len(argv):
        arg = argv[i]
        name, has_value, value = arg[2:].partition("=") if arg.startswith("--") else (None, False, None)
        if arg in ("-h", "--help"):
            opts["help"] = True
        elif name in OPTIONS:
            if not has_value:
                i += 1
                if i >= len(argv):
                    raise UsageError("--%s needs a value" % name)
                value = argv[i]
            if value not in OPTIONS[name]:
                raise UsageError("--%s must be one of %s, got %r" % (name, ", ".join(OPTIONS[name]), value))
            opts[name] = value
        elif arg.startswith("-") and len(arg) > 1:
            raise UsageError("unknown option %s" % arg)
        else:
            rest.append(arg)
        i += 1
