            (["name>Z"], ["beta", "gamma", "delta"]),
            (["city~LEED"], ["beta", "Alpha", "gamma"]),
            (["city~"], ["beta", "Alpha", "gamma", "delta", "Epsilon"]),
            (["name~a", "city~york"], ["delta"]),
